# s='aab': is_pal[0][1]=T(aa). dp[2]=0(b), dp[1]=1(ab→b=1cut), dp[0]: is_pal[0][0]T→1+dp[1]=2, is_pal[0][1]T→1+dp[2]=1. dp[0]=1 ✓

